        let ix = match edits.binary_search_by(|probe| probe.old.start.cmp(&old)) {
            Ok(ix) => ix,
            Err(ix) => {
                if ix == 0 {
                    return Edit {
                        old: old..old,
                        new: old..old,
                    };
                } else {
                    ix - 1
                }
            }
        };

        if let Some(edit) = edits.get(ix) {
            if old > edit.old.end {
                let translated = edit.new.end + (old - edit.old.end);
                Edit {
                    new: translated..translated,
                    old: old..old,
                }
            } else {
                edit.clone()
            }
        } else {
            Edit {
                old: old..old,
                new: old..old,
            }
        }
    }
}

