pub fn old_to_new(&self, old: T) -> T {
    let ix = match self.0.binary_search_by(|probe| probe.old.start.cmp(&old)) {
        Ok(ix) => ix,
        Err(ix) => {
            if ix == 0 {
                return old;
            } else {
                ix - 1
            }
        }
    };
    if let Some(edit) = self.0.get(ix) {
        if old >= edit.old.end {
            edit.new.end + (old - edit.old.end)
        } else {
            edit.new.start
        }
    } else {
        old
    }
}

